R=[
("सेब के साथ ब्रेज़्ड पत्ता गोभी",
"यह मीठा और नमकीन व्यंजन मौसमी सेब और पत्ता गोभी का उपयोग करके बजट के अनुकूल साइड सब्ज़ी बनाता है। भुने हुए पोर्क टेंडरलॉइन विद थाइम एंड गार्लिक मैरिनेड और बालसमिक भुने अंगूर जैसे सरल मांसाहारी मुख्य व्यंजन के साथ बढ़िया लगता है।",
"8","1/2 कप",
["3 छोटे चम्मच ऑलिव ऑयल","1/2 कप प्याज़ (बारीक कटा हुआ)","1 मध्यम ग्रैनी स्मिथ या अन्य खट्टा सेब (बिना छिला और बारीक कटा हुआ)","1/2 छोटा चम्मच शाही जीरा (कैरवे के बीज)","1/2 छोटा चम्मच चीनी","1/4 कप कम सोडियम वाला सब्ज़ी का शोरबा","3 कप लाल पत्ता गोभी (कद्दूकस/बारीक कटी हुई)","1/4 कप सेब का रस","1 बड़ा चम्मच सेब का सिरका (नींबू का रस)"],
["एक बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें। प्याज़ और सेब डालें और लगभग 3 से 4 मिनट भूनें, बस सेब के नरम होना शुरू होने तक। शाही जीरा और चीनी डालें और 1 मिनट भूनें।","पत्ता गोभी डालें और चिमटे से मिलाएँ, ताकि गोभी पर सेब और प्याज़ लिपट जाएँ। लगभग 3 से 4 मिनट भूनें।","शोरबा और सेब का रस डालें, ढक दें और मध्यम आँच पर लगभग 8 से 10 मिनट पकाएँ, या जब तक गोभी अंदर तक पक न जाए पर नरम रहे। सेब का सिरका या नींबू का रस छिड़कें।"],[]),
("शतावरी और लीक फ्रिटाटा",
"इस शतावरी और लीक फ्रिटाटा के साथ अपनी नाश्ते की दिनचर्या में नई जान डालें, जो आपके दिन की ऊर्जावान शुरुआत के लिए स्वादिष्ट और पौष्टिक विकल्प है। इस फ्रिटाटा में शतावरी की कुरकुरी ताज़गी और लीक की हल्की मिठास मिलती है, जो स्वादों की ऐसी जुगलबंदी बनाती है जो मधुमेह वाले लोगों के लिए भी अनुकूल है और सुबह की शुरुआत के लिए प्रोटीन से भरपूर तरीका भी है।",
"8","1 फाँक",
["2 कप अंडे का विकल्प","1/3 कप स्किम दूध","1/4 कप आंशिक रूप से वसा रहित मोज़रेला (कद्दूकस किया हुआ)","1/4 कप परमेसन चीज़ (कद्दूकस किया हुआ)","3/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ऑलिव ऑयल","1 कप लीक (अच्छी तरह धोए हुए, सफ़ेद और हल्के हरे हिस्से, कटे हुए)","1 गुच्छा (लगभग 2 1/2 कप) शतावरी (छँटी हुई, 1 इंच के तिरछे टुकड़ों में कटी हुई)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें।","एक मध्यम कटोरे में अंडे का विकल्प, दूध, चीज़, नमक और काली मिर्च को फेंटें और एक तरफ़ रख दें।","भारी तले की ओवन-सुरक्षित 10 इंच की कास्ट आयरन या नॉनस्टिक कड़ाही में मध्यम-धीमी आँच पर ऑलिव ऑयल डालें।","लीक डालें और 2 मिनट भूनें।","शतावरी डालें और नरम होने तक, लगभग 6 मिनट भूनें, बार-बार चलाते रहें ताकि लीक बराबर भूरा हो।","अंडे का मिश्रण कड़ाही में डालें और धीरे से मिलाएँ। किनारों को जमने दें, फिर पहले से गरम ओवन में रखें और फ्रिटाटा के फूलने और सुनहरा होने तक 10–15 मिनट बेक करें।","8 फाँकों में काटें और परोसें।"],[]),
("पिस्ता की परत वाला सैल्मन",
"यह बेहद झटपट और आसान रात का खाना है जो सेहतमंद वसा और प्रोटीन से भरपूर है।",
"4","1 फ़िले",
["6 बड़े चम्मच पिस्ता (छिले हुए, बारीक कटे हुए)","1/4 कप कुट्टू का आटा","2 बड़े अंडों की सफ़ेदी (फेंटी हुई)","4 साबुत सैल्मन (4 औंस के फ़िले)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक उथले बर्तन में पिस्ता और आटा मिलाएँ। दूसरे उथले बर्तन में अंडे की सफ़ेदी डालें।","सैल्मन के एक तरफ़ को अंडे की सफ़ेदी में डुबोएँ और फिर पिस्ता के मिश्रण में दबाएँ।","फ़िले को मेवे वाली तरफ़ ऊपर करके नॉनस्टिक बेकिंग शीट पर रखें।","बाकी तीन फ़िले के लिए यही दोहराएँ। फ़िले के ऊपरी हिस्से पर कुकिंग स्प्रे करें।","25 मिनट बेक करें।"],[]),
("चिकन, मशरूम और जौ का सूप",
"जौ को पहले से ज़्यादा मात्रा में पकाने के हमारे सुझावों के साथ, यह सूप सप्ताह के किसी भी दिन का झटपट और आसान भोजन बन सकता है। अगर आपके पास समय कम है, तो प्याज़, गाजर और सेलेरी का पहले से कटा हुआ मिश्रण ले आएँ।",
"8","1 कप",
["2 छोटे चम्मच ऑलिव ऑयल","1 मध्यम प्याज़ (बारीक कटा हुआ)","2 मध्यम गाजर (बारीक कटी हुई)","3 डंठल अजवाइन के डंठल/सेलेरी (बारीक कटे हुए)","1 पाउंड सफ़ेद (बटन) मशरूम (कटे हुए)","32 औंस कम सोडियम वाला चिकन शोरबा (वसा रहित)","1 टहनी ताज़ा थाइम","2 तेज पत्ते","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","1 कप पका हुआ जौ","2 कप पका हुआ चिकन (कसा हुआ/रेशे किया हुआ)"],
["सूप के बर्तन में मध्यम आँच पर तेल डालें। प्याज़, गाजर, सेलेरी और मशरूम डालें। 5 मिनट भूनें।","शोरबा, थाइम, तेज पत्ते, नमक और काली मिर्च डालें। उबाल आने दें, फिर आँच धीमी करके ढककर 20 मिनट पकाएँ।","तेज पत्ते और थाइम का डंठल निकालें। जौ और चिकन डालें और 2-3 मिनट तक गरम करें।","नोट: जौ को ज़्यादा मात्रा में पकाने के लिए, 11 औंस सूखा पर्ल (जल्दी पकने वाला) जौ 4 कप उबलते पानी वाले बर्तन में डालें। ढक दें, फिर 10-12 मिनट धीमी आँच पर पकाएँ। आँच से उतारें और आँच से हटाकर 5 मिनट ढका रहने दें। इससे 6 कप पका हुआ जौ बनता है। इस जौ को पके हुए जौ की ज़रूरत वाली किसी भी रेसिपी में उपयोग किया जा सकता है। वायुरोधी डिब्बे में फ्रिज में 7 दिन तक रखें या फ़्रीज़र बैग में 1-1 कप की मात्रा में पैक करके 6 महीने तक रखें।"],[]),
("तिल-सोया सलाद ड्रेसिंग",
"घर पर अपनी सलाद ड्रेसिंग बनाना जल्दी और आसान है, और इससे आप नमक, चीनी और अन्य सामग्री को नियंत्रित कर सकते हैं।",
"16","1 बड़ा चम्मच",
["1/4 कप कम सोडियम वाली सोया सॉस","1/4 कप राइस विनेगर","1/4 कप एवोकाडो ऑयल","2 बड़े चम्मच तिल का तेल (भुने तिल का)","1 बड़ा चम्मच एरिथ्रिटॉल (या अन्य चीनी का विकल्प)"],
["सभी सामग्री को कसकर बंद होने वाले ढक्कन वाले जार में डालें। सब कुछ अच्छी तरह मिलने तक ज़ोर से हिलाएँ। ड्रेसिंग को जार में फ्रिज में 2 सप्ताह तक रखें। अगर यह अलग हो जाए, तो उपयोग से ठीक पहले फिर हिला लें।"],[]),
("पीनट बटर साबुत अनाज टोस्ट",
"यह सरल, संतोषजनक नाश्ता या स्नैक गरम साबुत अनाज के टोस्ट को मलाईदार पीनट बटर के साथ जोड़ता है, जो लंबे समय तक ऊर्जा और रक्त ग्लूकोज़ (ब्लड शुगर) के प्रबंधन में मदद करता है। यह पेट भरने वाली रेसिपी कुछ ही मिनटों में तैयार हो जाती है।",
"1","1 स्लाइस",
["1 1/2 बड़े चम्मच प्राकृतिक पीनट बटर","1 स्लाइस साबुत अनाज का टोस्ट"],
["साबुत अनाज की ब्रेड के एक स्लाइस को अपनी पसंद के कुरकुरेपन तक टोस्ट करें।","गरम टोस्ट पर 1.5 बड़े चम्मच पीनट बटर बराबर फैलाएँ।","टोस्ट के गरम रहते ही तुरंत परोसें।"],[]),
("पीनट सॉस के साथ सब्ज़ियों वाले स्प्रिंग रोल",
"यह रेसिपी बढ़िया स्टार्टर बनाती है, लेकिन रोल में चिकन या पोर्क जैसा कोई दुबला प्रोटीन डालें तो यह हल्का भोजन बन जाता है। समय बचाने के लिए, पत्ता गोभी और गाजर वाला बैग में मिलने वाला कोलस्लॉ मिक्स उपयोग करें।",
"12","1 रोल और लगभग 1 बड़ा चम्मच सॉस",
["1 कप पत्ता गोभी (कद्दूकस की हुई)","1 मध्यम गाजर (कद्दूकस की हुई)","1 कप खीरा (छिला हुआ, बीज निकाला हुआ और बारीक कटा हुआ)","1/4 कप + 2 बड़े चम्मच ताज़ा हरा धनिया (कटा हुआ, बाँटकर उपयोग करें)","1 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","1/4 कप पीनट बटर (माइक्रोवेव में 30 सेकंड गरम किया हुआ)","3 बड़े चम्मच सोया सॉस (ग्लूटेन-मुक्त)","3 बड़े चम्मच राइस वाइन विनेगर","2 बड़े चम्मच गरम पानी","1 बड़ा चम्मच कैनोला ऑयल","1/4 छोटा चम्मच कुचली हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","1 कली लहसुन (बारीक कटी हुई)","12 साबुत स्प्रिंग रोल शीट"],
["एक मध्यम कटोरे में पत्ता गोभी, गाजर, खीरा, 1/4 कप हरा धनिया और हरा प्याज़ मिलाएँ।","एक छोटे कटोरे में पीनट बटर, सोया सॉस, सिरका, पानी, तेल, मिर्च के फ्लेक्स, लहसुन और बचे हुए 2 बड़े चम्मच हरे धनिये को फेंटकर मिलाएँ।","उपयोग से पहले, स्प्रिंग रोल शीट को 10-15 सेकंड पानी में भिगोएँ और अतिरिक्त पानी झटक दें। शीट के निचले हिस्से में लगभग 1/4 कप सब्ज़ी का मिश्रण रखें। अपने सबसे पास वाले किनारे को मोड़कर भरावन को ढकें। बगल के किनारों को कसकर अंदर की ओर मोड़ें। बंद करने के लिए आगे की ओर लपेटें। बाकी 11 स्प्रिंग रोल के लिए यही प्रक्रिया दोहराएँ।","स्प्रिंग रोल को पीनट सॉस के साथ परोसें।"],[]),
("पीली स्क्वैश के साथ कोलार्ड ग्रीन्स",
"कोलार्ड ग्रीन्स एक पोषक सुपरफ़ूड है, जिसमें कई ज़रूरी विटामिन और खनिज भरपूर होते हैं। दक्षिणी व्यंजनों में कोलार्ड पारंपरिक रूप से सूअर की बहुत सारी चर्बी और नमक के साथ बनाए जाते हैं, लेकिन इस रूप में संतृप्त वसा और सोडियम के बिना भी पूरा स्वाद मिलता है। अपनी प्लेट पूरी करें: इस सब्ज़ी साइड डिश को लहसुन और रोज़मेरी के साथ नींबू चिकन जैसे प्रोटीन वाले मुख्य व्यंजन और एक साधारण भुने शकरकंद के साथ जोड़ें।",
"4","3/4 कप",
["1 गुच्छा कोलार्ड ग्रीन्स (लगभग 8 औंस, धोए और सुखाए हुए)","2 बड़े चम्मच ऑलिव ऑयल","2 स्लाइस टर्की बेकन","2 कली लहसुन (बारीक कटी हुई)","1 मध्यम पीली स्क्वैश (अर्धचंद्र आकार में कटी हुई)","1 कप कम सोडियम वाला सब्ज़ी का शोरबा","1/8 छोटा चम्मच काली मिर्च"],
["कोलार्ड की पत्तियों के बीच में जाने वाले सख़्त डंठल निकाल दें। कई पत्तियों को सलीके से एक के ऊपर एक रखें और कसकर लपेटें, फिर पट्टियों में काट लें। बाकी कोलार्ड ग्रीन्स के लिए यही दोहराएँ।","एक मध्यम सॉते पैन में मध्यम आँच पर 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। जब तेल में लहरें दिखने लगें, तो टर्की बेकन डालें और हर तरफ़ 3 मिनट तक सुनहरा भूरा होने तक पकाएँ। बेकन निकालकर थोड़ा ठंडा होने के लिए एक तरफ़ रख दें। ठंडा होने पर बेकन को छोटे टुकड़ों में काट लें।","उसी सॉते पैन में मध्यम आँच पर बचा हुआ 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। जब तेल में लहरें दिखने लगें, तो लहसुन डालें और खुशबू आने तक, 30 सेकंड पकाएँ।","कोलार्ड ग्रीन्स और स्क्वैश डालें और कोलार्ड के मुरझाने और स्क्वैश के नरम होना शुरू होने तक, लगभग 5 मिनट पकाएँ।","सब्ज़ी का शोरबा डालें और मिश्रण को उबालें। आँच कम करें और ढककर सब्ज़ियों के अंदर तक पकने तक, 10 मिनट धीमी आँच पर पकाएँ।","1/8 छोटा चम्मच नमक (*वैकल्पिक), काली मिर्च और पकी हुई टर्की बेकन डालें और मिलाने के लिए चलाएँ। *वैकल्पिक नमक पोषण विश्लेषण में शामिल नहीं है; 1/8 छोटा चम्मच नमक प्रति सर्विंग 75 मिलीग्राम सोडियम जोड़ता है।"],[]),
("ग्रिल्ड चिकन पर स्ट्रॉबेरी-जलापेनो सालसा",
"ग्रिल्ड चिकन पर यह बहुत कम कार्बोहाइड्रेट और कम सोडियम वाला स्ट्रॉबेरी जलापेनो सालसा एक ताज़ा और स्वादिष्ट व्यंजन है। रसीली स्ट्रॉबेरी मिठास जोड़ती हैं, जबकि जलापेनो हल्का तीखापन देती है। ग्रिल्ड चिकन के साथ, यह एक ही आसान भोजन में मीठे, तीखे और नमकीन स्वादों के मेल का आनंद लेने का सरल तरीका है।",
"6","1 चिकन ब्रेस्ट + 2 बड़े चम्मच सालसा",
["3 साबुत बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (आधे-आधे कटे हुए, हर एक 8 औंस)","3 स्प्रे, 0.75 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ी दरदरी पिसी)","1 पिंट ताज़ी स्ट्रॉबेरी (छोटी, बारीक कटी हुई)","4 मध्यम रोमा (प्लम) टमाटर (बीज निकाले और छोटे टुकड़ों में कटे हुए)","1 छोटा शैलट (बारीक कटा हुआ)","1 छोटी जलापेनो मिर्च (बारीक कटी हुई)","2 बड़े चम्मच ताज़ा नींबू का रस","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","2 कली लहसुन (बारीक कटी हुई)","1/4 कप ताज़ा हरा धनिया (ढीला भरा हुआ, कटा हुआ)"],
["ग्रिल पैन को मध्यम-तेज़ आँच पर पहले से गरम करें। चिकन पर नमक और काली मिर्च लगाएँ और हल्का कुकिंग स्प्रे करें। चिकन को हर तरफ़ 6–7 मिनट तक, अंदर तक पकने तक ग्रिल करें।","इस बीच, स्ट्रॉबेरी, टमाटर, शैलट, जलापेनो, नींबू का रस, लहसुन, ऑलिव ऑयल और हरे धनिये को मिलाकर सालसा बनाएँ। मिलाने के लिए चलाएँ।","चिकन को प्लेटों में बाँटें और ऊपर से सालसा डालें।"],[]),
("भरवाँ ब्रसेल्स स्प्राउट बाइट्स – फ़ूडी रेसिपी",
"ये छुट्टियों के लिए अनोखा स्टार्टर या साइड डिश बनते हैं, जो आपके मेहमानों को बहुत पसंद आएगा।",
"12","2 बाइट्स",
["12 बड़े ताज़े ब्रसेल्स स्प्राउट","1 बड़ा चम्मच ऑलिव ऑयल","3 स्लाइस दुबला टर्की बेकन (छोटे टुकड़ों में कटा हुआ)","1 कली लहसुन (बारीक कटी हुई)","3 औंस बकरी का चीज़ (शेव्र) (मुलायम)","2 बड़े चम्मच स्किम दूध","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच परमेसन चीज़ (कद्दूकस किया हुआ)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","ब्रसेल्स स्प्राउट के सिरे काटें और उन्हें लंबाई में आधा काट लें। एक बड़े बर्तन में पानी उबालें और स्प्राउट को 2 मिनट ब्लांच करें, पानी निथारें और एक तरफ़ रख दें।","खरबूजा स्कूपर या छोटे चम्मच के नाप से स्प्राउट का बीच का हिस्सा निकालें, खोल अलग रख दें और निकाले गए हिस्से को मोटा-मोटा काट लें।","एक मध्यम सॉते पैन में मध्यम आँच पर ऑलिव ऑयल डालें। बेकन डालें और लगभग कुरकुरा होने तक भूनें। कटे हुए स्प्राउट और लहसुन डालें और स्प्राउट के नरम होने तक 3-4 मिनट और भूनें।","एक कटोरे में बकरी का चीज़, दूध, नमक (वैकल्पिक), काली मिर्च और परमेसन चीज़ मिलाएँ। भुना हुआ बेकन और स्प्राउट डालें और अच्छी तरह मिलाएँ।","भरावन के मिश्रण को हर स्प्राउट के खोल में बराबर बाँटकर भरें (लगभग एक ढेर वाला छोटा चम्मच)। स्प्राउट को बेकिंग शीट पर रखें और 20 मिनट तक, या भरे हुए स्प्राउट के सुनहरा भूरा होने तक बेक करें। गरम परोसें।"],[]),
("इंग्रिड हॉफ़मैन का चिकन टिंगा पोब्लाना",
"मेक्सिको के प्यूब्ला का यह पारंपरिक मैक्सिकन स्ट्यू स्वाद और मसालों में बेहद भरपूर है। यह हर बार मन को तृप्त कर देता है। इसे टॉर्टिला के अंदर या ब्राउन राइस या क्विनोआ के कटोरे पर परोसें और आनंद लें! इस व्यंजन को अलग अंदाज़ में बनाने के लिए, चिकन की जगह दुबला पोर्क लॉइन इस्तेमाल करें।",
"4","3/4 कप",
["1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट","2 तेज पत्ते","1 (14.5 औंस) कैन बिना नमक मिलाए छोटे कटे हुए टमाटर","1/4 कप और 2 बड़े चम्मच ताज़ा हरा धनिया (कटा हुआ और बाँटकर उपयोग करें)","2 साबुत एडोबो में चिपोटले मिर्च","2 बड़े चम्मच चिपोटले के एडोबो सॉस","1 बड़ा चम्मच सेब का सिरका","2 कली लहसुन (कटी हुई)","1/2 छोटा चम्मच सूखा थाइम","1/2 छोटा चम्मच सूखा मार्जोरम या सूखा ओरेगानो","1/8 छोटा चम्मच नमक","1 बड़ा चम्मच कैनोला ऑयल","1 मध्यम प्याज़ (पतला कटा हुआ)"],
["चिकन, तेज पत्ते और डूबने भर का ठंडा पानी एक मध्यम सॉसपैन में रखें; धीमी आँच पर उबालें। ढककर चिकन के पूरी तरह पकने तक, लगभग 15 मिनट धीमी आँच पर पकाएँ; पानी निथार लें। तेज पत्ते निकाल दें। चिकन को कटिंग बोर्ड पर रखें। ठंडा होने दें, फिर दो काँटों से रेशे-रेशे कर लें। एक तरफ़ रख दें।","इस बीच, टमाटर, 1/4 कप हरा धनिया, चिपोटले मिर्च, एडोबो सॉस, सिरका, लहसुन, थाइम, मार्जोरम और नमक को फ़ूड प्रोसेसर या ब्लेंडर में प्यूरी करें।","एक बड़ी नॉनस्टिक कड़ाही में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़ डालें और बीच-बीच में चलाते हुए प्याज़ के नरम होने तक, लगभग 8 मिनट पकाएँ। टमाटर का मिश्रण और रेशे किया हुआ चिकन डालें। मध्यम आँच पर बीच-बीच में चलाते हुए, स्वादों के मिलने और चिकन के गरम होने तक, लगभग 10 मिनट पकाएँ। ऊपर से बचा हुआ 2 बड़े चम्मच हरा धनिया छिड़कें।"],[]),
("स्लो कुकर में बना मीट लोफ़",
"इस मीट लोफ़ को स्लो कुकर में पकाने का मतलब है कि आप दफ़्तर में लंबे दिन के बाद घर आकर तैयार रात का खाना पा सकते हैं! बीफ़ की जगह टर्की का कीमा डाला गया है, जिससे यह आरामदायक पारंपरिक व्यंजन मधुमेह के लिए और अनुकूल बनता है। यह रेसिपी \"द न्यू सोल फ़ूड कुकबुक फ़ॉर पीपल विद डायबिटीज़\" में मिल सकती है।",
"8","4 औंस",
["2 बड़े अंडे","3/4 कप 1% दूध","2/3 कप सूखे मसालेदार ब्रेड क्रम्ब्स","2 छोटे चम्मच सूखा कटा प्याज़","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच सूखी सेज","1/2 छोटा चम्मच सौंफ़","1/2 कप (लगभग 2 1/2 औंस) सफ़ेद (बटन) मशरूम (बारीक कटे हुए)","2 पाउंड दुबला टर्की का कीमा (कम से कम 95% दुबला)","1/4 कप केचप","2 बड़े चम्मच ब्राउन शुगर","1 छोटा चम्मच सरसों का पाउडर","1/2 छोटा चम्मच वोस्टरशर सॉस"],
["एक बड़े कटोरे में अंडे, दूध, ब्रेड क्रम्ब्स, प्याज़, नमक, सेज, सौंफ़ और मशरूम मिलाएँ। मिश्रण के ऊपर टर्की का कीमा तोड़कर डालें और अच्छी तरह मिलाने के लिए चलाएँ।","इसे गोल लोफ़ का आकार दें; 5 क्वार्ट के स्लो कुकर में रखें। ढक दें और मीट थर्मामीटर के 165°F दिखाने तक, 5–6 घंटे धीमी आँच पर पकाएँ। (या, चाहें तो 350°F के ओवन में [कन्वेक्शन ओवन के लिए 325°F] 35–45 मिनट बेक करें, जब तक मांस का अंदरूनी तापमान 165°F न हो जाए।)","एक छोटे कटोरे में केचप, ब्राउन शुगर, सरसों और वोस्टरशर सॉस को फेंटें; सॉस को मीट लोफ़ के ऊपर चम्मच से डालें। वापस स्लो कुकर में रखें और गरम होने तक, लगभग 15 मिनट धीमी आँच पर पकाएँ। काटने से पहले 10 मिनट रखा रहने दें।"],[]),
("दक्षिणी शलजम के पत्ते और लोबिया",
"दक्षिणी शलजम के पत्ते और लोबिया एक पारंपरिक और आरामदायक व्यंजन है जो डायटरी अप्रोचेज़ टू स्टॉप हाइपरटेंशन (DASH) भोजन पैटर्न में फिट बैठता है, यानी यह उन लोगों के लिए अच्छा विकल्प है जो अपने रक्तचाप का ध्यान रखते हैं। नरम शलजम के पत्तों को प्याज़, लहसुन और थोड़े से सिरके के साथ धीमी आँच पर पकाया जाता है, फिर स्मोक्ड पेपरिका और थाइम से मसालेदार मलाईदार लोबिया के साथ परोसा जाता है। यह स्वादिष्ट और भरपेट भोजन है जो दक्षिणी व्यंजनों का सार समेटे हुए है।",
"4","1/2 कप पत्ते और 1/4 कप बीन्स",
["2 बड़े चम्मच ऑलिव ऑयल (बाँटकर)","2 छोटे पीले प्याज़ (बारीक कटे हुए, बाँटकर उपयोग करें)","2 कली लहसुन (बारीक कटी हुई)","1 पाउंड शलजम के पत्ते (धोए और कटे हुए (या लगभग 8 कप दबाकर भरे हुए))","3/4 छोटा चम्मच स्मोक्ड पेपरिका (बाँटकर)","1/4 छोटा चम्मच कुचली हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च (बाँटकर)","2 कप कम सोडियम वाला सब्ज़ी का शोरबा (बाँटकर)","1 बड़ा चम्मच सेब का सिरका","1 कप पका हुआ लोबिया (छाना और धोया हुआ)","1 छोटा टमाटर (बारीक कटा हुआ)","1/4 छोटा चम्मच लाल मिर्च (कायेन पेपर)","2 बड़े चम्मच ताज़ा अजमोद (कटा हुआ)","1/4 छोटा चम्मच हॉट सॉस"],
["एक बड़ी कड़ाही या बर्तन में मध्यम आँच पर ऑलिव ऑयल गरम करें। कटा हुआ प्याज़ डालें और नरम होने तक 3–4 मिनट भूनें। लहसुन डालें और खुशबू आने तक 1 मिनट पकाएँ।","कटे हुए शलजम के पत्ते, 1/4 छोटा चम्मच स्मोक्ड पेपरिका, लाल मिर्च के फ्लेक्स और 1/4 छोटा चम्मच काली मिर्च मिलाएँ। 1 कप सब्ज़ी का शोरबा डालें और धीमी आँच पर उबलने दें।","ढक दें और बीच-बीच में चलाते हुए पत्तों के नरम होने तक 15–20 मिनट पकाएँ। परोसने से ठीक पहले सेब का सिरका मिलाएँ।","दूसरी कड़ाही में मध्यम आँच पर 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। बचा हुआ कटा प्याज़ डालें और नरम होने तक 3–4 मिनट भूनें।","लोबिया, कटा टमाटर, 1/2 छोटा चम्मच स्मोक्ड पेपरिका, लाल मिर्च (कायेन पेपर) और 1/4 छोटा चम्मच काली मिर्च मिलाएँ। 1 कप सब्ज़ी का शोरबा डालें और बीच-बीच में चलाते हुए, स्वादों के मिलने और तरल के थोड़ा कम होने तक 10–15 मिनट धीमी आँच पर पकाएँ।","शलजम के पत्ते और लोबिया को 4 प्लेटों या कटोरों में बाँटें। ताज़े अजमोद और चाहें तो चुटकी भर हॉट सॉस से सजाएँ।"],[]),
("लहसुन के साथ वेनिस शैली के झींगे (शिए आलियो ओलियो)",
"यह व्यंजन आम तौर पर वेनिस के चिचेत्ती बार में परोसा जाता है।",
"8","2 औंस झींगे",
["1 पाउंड छोटे झींगे (छिले हुए और नस निकाले हुए)","2 बड़े चम्मच नींबू का रस (बड़े नींबू का)","2 कली लहसुन","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1 कप ताज़ा अजमोद (कटा हुआ)","1/4 छोटा चम्मच महीन समुद्री नमक"],
["4 क्वार्ट के बर्तन में पानी भरकर उबालें। झींगों को बाहर से गुलाबी और अंदर से अपारदर्शी होने तक, लगभग 3 मिनट उबालें। छेद वाले चम्मच से बर्तन से निकालें। नींबू का रस, लहसुन, एक्स्ट्रा वर्जिन ऑलिव ऑयल, अजमोद और नमक के साथ मिलाएँ।","थोड़े पके हुए पोलेंटा के साथ परोसें या इस मिश्रण को हरे सलाद के ऊपर डालें।"],[]),
("तोरी के चिप्स",
"तोरी के चिप्स पारंपरिक आलू चिप्स का स्वादिष्ट और हल्का विकल्प हैं। मधुमेह के अनुकूल इस स्नैक के साथ कुरकुरे रूप में तोरी की प्राकृतिक मिठास और बनावट का आनंद लें।",
"4","1/2 कप",
["1/4 कप परमेसन चीज़ (कद्दूकस किया हुआ)","1/4 कप ब्रेड क्रम्ब्स","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच पेपरिका","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 मध्यम तोरी/ज़ुकीनी (गोल आकार में पतली कटी हुई)","1 बड़ा चम्मच ऑलिव ऑयल"],
["अपने ओवन को 425 डिग्री F पर पहले से गरम करें और बेकिंग शीट पर चर्मपत्र कागज़ बिछाएँ।","एक मिक्सिंग बाउल में कद्दूकस किया परमेसन चीज़, ब्रेड क्रम्ब्स, लहसुन पाउडर, पेपरिका, नमक और काली मिर्च मिलाएँ। तोरी के चिप्स के लिए स्वादिष्ट परत बनाने के लिए इन सूखी सामग्रियों को अच्छी तरह मिलाएँ।","तोरी को गोल आकार में पतला काटें। बराबर गोल टुकड़ों के लिए आप चाकू या मैंडोलिन का उपयोग कर सकते हैं।","तोरी के टुकड़ों को ऑलिव ऑयल में तब तक मिलाएँ जब तक उन पर हल्की परत न चढ़ जाए।","हर तोरी के टुकड़े को तैयार परत वाले मिश्रण में डुबोएँ, ध्यान रखें कि दोनों तरफ़ बराबर परत लगे।","परत चढ़े तोरी के टुकड़ों को बेकिंग शीट पर एक परत में रखें।","पहले से गरम ओवन में लगभग 20 मिनट तक, या तोरी के चिप्स के सुनहरा भूरा और कुरकुरा होने तक बेक करें।"],[]),
]
